import{_ as a,o as i,c as r,a4 as l}from"./chunks/framework.cM03Lg2X.js";const p=JSON.parse('{"title":"工程经验与踩坑","description":"从 Ebitengine 桌面应用和 verl 训练环境故障中提炼的可复用工程守则。","frontmatter":{"title":"工程经验与踩坑","description":"从 Ebitengine 桌面应用和 verl 训练环境故障中提炼的可复用工程守则。"},"headers":[],"relativePath":"shed/engineering-notes.md","filePath":"shed/engineering-notes.md","lastUpdated":1786332289000}'),n={name:"shed/engineering-notes.md"};function t(o,e,h,d,c,s){return i(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="工程经验与踩坑" tabindex="-1">工程经验与踩坑 <a class="header-anchor" href="#工程经验与踩坑" aria-label="Permalink to “工程经验与踩坑”">​</a></h1><p>本页合并 Notion「知识条目」与「踩坑记录」。两个同名的 Ebitengine 中文渲染记录内容重复，站内只保留一份结论。</p><h2 id="go-ebitengine-桌面像素应用" tabindex="-1">Go + Ebitengine 桌面像素应用 <a class="header-anchor" href="#go-ebitengine-桌面像素应用" aria-label="Permalink to “Go + Ebitengine 桌面像素应用”">​</a></h2><h3 id="技术选择" tabindex="-1">技术选择 <a class="header-anchor" href="#技术选择" aria-label="Permalink to “技术选择”">​</a></h3><p>Go + Ebitengine 适合低占用桌面小工具：可编译为单文件、运行时依赖少，并支持透明窗口、置顶和无边框。它的优势来自明确的小型 2D 场景，不应扩展成所有桌面 UI 的通用选择。</p><h3 id="精灵与动画" tabindex="-1">精灵与动画 <a class="header-anchor" href="#精灵与动画" aria-label="Permalink to “精灵与动画”">​</a></h3><ul><li>用数字矩阵表示颜色区域，运行时映射皮肤；一套形状可复用多套配色。</li><li>用 Pixel Delta 记录变更像素，适合低分辨率动作。</li><li>配饰作为独立叠加层，不修改基础精灵。</li><li>动作与台词使用独立随机定时器，避免相互阻塞和机械节奏。</li><li>固定窗口尺寸配合 hover 显隐，比动态缩放更稳定。</li></ul><h3 id="透明窗口-ui" tabindex="-1">透明窗口 UI <a class="header-anchor" href="#透明窗口-ui" aria-label="Permalink to “透明窗口 UI”">​</a></h3><p>透明窗口上不适合覆盖大块不透明背景。交互元素应尽量与像素视觉语言一致，并检查拖拽、焦点和点击区域是否仍然清晰。</p><h2 id="踩坑一-debugprint-不显示中文" tabindex="-1">踩坑一：DebugPrint 不显示中文 <a class="header-anchor" href="#踩坑一-debugprint-不显示中文" aria-label="Permalink to “踩坑一：DebugPrint 不显示中文”">​</a></h2><h3 id="症状" tabindex="-1">症状 <a class="header-anchor" href="#症状" aria-label="Permalink to “症状”">​</a></h3><p><code>ebitenutil.DebugPrintAt</code> 渲染中文或 emoji 时，文字被静默跳过，只看到背景，不抛出错误。</p><h3 id="根因" tabindex="-1">根因 <a class="header-anchor" href="#根因" aria-label="Permalink to “根因”">​</a></h3><p>内置 bitmap 字体只覆盖 ASCII 可打印字符（<code>0x20—0x7E</code>），不是完整 Unicode 字体。这是能力边界，不是业务逻辑 bug。</p><h3 id="方案" tabindex="-1">方案 <a class="header-anchor" href="#方案" aria-label="Permalink to “方案”">​</a></h3><ul><li>如果像素风允许，只使用 ASCII，保持零额外字体依赖；</li><li>如果必须显示中文，使用 <code>text/v2</code> 加载支持 CJK 的 <code>.ttf</code>，并接受二进制体积增长。</li></ul><h3 id="可复用规则" tabindex="-1">可复用规则 <a class="header-anchor" href="#可复用规则" aria-label="Permalink to “可复用规则”">​</a></h3><p>在确定文案系统前先做最小字符集渲染测试，覆盖中文、标点、emoji 和目标平台字体打包。</p><h2 id="踩坑二-verl-启动失败形成版本错误链" tabindex="-1">踩坑二：verl 启动失败形成版本错误链 <a class="header-anchor" href="#踩坑二-verl-启动失败形成版本错误链" aria-label="Permalink to “踩坑二：verl 启动失败形成版本错误链”">​</a></h2><h3 id="症状-1" tabindex="-1">症状 <a class="header-anchor" href="#症状-1" aria-label="Permalink to “症状”">​</a></h3><p>一次 GRPO 训练启动先后暴露 <code>transformers</code> 导入、FSDP wrap policy、vLLM API、CUDA kernel、显存 profiling 和 sampler OOM 等九类错误。逐个 monkey patch 只能不断揭开下一层不兼容。</p><h3 id="根因-1" tabindex="-1">根因 <a class="header-anchor" href="#根因-1" aria-label="Permalink to “根因”">​</a></h3><ul><li><code>transformers</code> 已升级到 5.2.0，而旧版 verl 预期 4.x；</li><li>vLLM 是自定义 dev build，版本号与实际 API 不一致；</li><li>Ray Worker 不继承主进程的 <code>PYTHONPATH</code> patch；</li><li>共享 GPU 中其他进程释放显存，会让 vLLM profiling 的假设失效。</li></ul><h3 id="最终处理方向" tabindex="-1">最终处理方向 <a class="header-anchor" href="#最终处理方向" aria-label="Permalink to “最终处理方向”">​</a></h3><p>升级 verl 核心代码以恢复与新依赖的大范围兼容，只对自定义 vLLM 的版本/API 差异做少量定向 patch，并降低 <code>gpu_memory_utilization</code>、<code>max_num_seqs</code>，关闭冲突的 offload 配置。</p><h3 id="更重要的诊断顺序" tabindex="-1">更重要的诊断顺序 <a class="header-anchor" href="#更重要的诊断顺序" aria-label="Permalink to “更重要的诊断顺序”">​</a></h3><ol><li>先输出 Python、CUDA、torch、transformers、vLLM、训练框架版本；</li><li>与框架 lockfile / requirements / 官方兼容矩阵比对；</li><li>判断问题是单点 API 变化还是整体版本漂移；</li><li>整体漂移时优先恢复可复现环境或升级框架，不连续叠加 monkey patch；</li><li>使用容器或锁定环境保存最终可运行组合；</li><li>在独占或已知负载的 GPU 上做显存与性能验证。</li></ol><h2 id="工程守则摘要" tabindex="-1">工程守则摘要 <a class="header-anchor" href="#工程守则摘要" aria-label="Permalink to “工程守则摘要”">​</a></h2><ul><li>先验证依赖契约，再解释表面错误。</li><li>最小复现必须进入真实子进程 / Worker 环境。</li><li>一次补丁解决一个已证实的不兼容，不用 patch 掩盖版本矩阵失控。</li><li>对“成功启动”继续验证训练指标、显存、输出产物和可重复启动。</li><li>重复踩坑条目在展示层合并，但在 <a href="/knowledge-summary/appendix/notion-sources">Notion 来源索引</a> 保留两个源记录。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li><a href="https://app.notion.com/p/Ebitengine-33c3a54bd6b481df8a64ff98f674358f" target="_blank" rel="noreferrer">Notion：Ebitengine 桌面像素应用开发经验</a></li><li><a href="https://app.notion.com/p/Ebitengine-DebugPrint-33c3a54bd6b481c29d2fd39a54f60cec" target="_blank" rel="noreferrer">Notion：DebugPrint 中文渲染记录 A</a></li><li><a href="https://app.notion.com/p/Ebitengine-DebugPrint-33c3a54bd6b48181b973f809fab6a09e" target="_blank" rel="noreferrer">Notion：DebugPrint 中文渲染记录 B</a></li><li><a href="https://app.notion.com/p/verl-RL-9-33c3a54bd6b481f8a321c1a78c271d7f" target="_blank" rel="noreferrer">Notion：verl 环境版本漂移记录</a></li></ul>',31)])])}const f=a(n,[["render",t]]);export{p as __pageData,f as default};
